package com.example.tracking;import com.example.tracking.model.LifecycleEvent;import java.time.Instant;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class LifecycleEventTests{@Test void retainsStableSchemaAndIdentity(){var event=new LifecycleEvent(1,"event-1","order-1","customer-1","PAYMENT","COMPLETED",null,Instant.EPOCH);assertThat(event.schemaVersion()).isEqualTo(1);assertThat(event.eventId()).isEqualTo("event-1");assertThat(event.orderId()).isEqualTo("order-1");assertThat(event.status()).isEqualTo("COMPLETED");}}
